#!/usr/bin/env python3
"""
Round 107b tiles patch (28 September 2026), beside round107b_culprits.py.

  scripts/threat_index.py, threat/   deleted (the owner dropped the threat index).
  scripts/inpe_fire.py   new: INPE's 2023 fire detections cut into
                         tiles/inpe_fire_2023.pmtiles (source in round107c).
  attacks/               the Pastoral Land Commission's case tables (areas,
                         land, water, overexploitation, slave labour) and Land
                         of Resistance with dates of birth and photo links.

Whole files, written only where they differ. Run from the repository root.
"""
import base64, gzip, pathlib

FILES = {'scripts/inpe_fire.py': ('', True), 'attacks/land_of_resistance.geojson': ('', True), 'attacks/build.json': ('', True), 'attacks/cpt_areas_of_conflict.geojson': ('', True), 'attacks/cpt_land_conflicts.geojson': ('', True), 'attacks/cpt_water_conflicts.geojson': ('', True), 'attacks/cpt_overexploitation.geojson': ('', True), 'attacks/cpt_slave_labour_cases.geojson': ('', True)}
DELETE = ['scripts/threat_index.py', 'threat']

if not pathlib.Path("scripts").is_dir():
    raise SystemExit("round107b: scripts/ not found; run from the culprits-tiles-more root")
changed = []
for path, (b64, gz) in FILES.items():
    p = pathlib.Path(path)
    new = base64.b64decode(b64)
    if gz:
        new = gzip.decompress(new)
    if p.exists() and p.read_bytes() == new:
        continue
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(new)
    changed.append(path)
for path in DELETE:
    p = pathlib.Path(path)
    if p.is_dir():
        import shutil; shutil.rmtree(p); changed.append("deleted " + path)
    elif p.exists():
        p.unlink(); changed.append("deleted " + path)
print("round107b: " + (", ".join(changed) if changed else "nothing to change (already applied)"))
